export function parseCsv(text) {
  if (text === undefined || text === null || text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  // True right after a row-ending newline, so a trailing break adds no empty row.
  let endedRow = false;

  const endRow = () => {
    row.push(field);
    field = '';
    rows.push(row);
    row = [];
    endedRow = true;
  };

  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      endedRow = false;
      continue;
    }

    if (ch === '"') {
      inQuotes = true;
      endedRow = false;
    } else if (ch === ',') {
      row.push(field);
      field = '';
      endedRow = false;
    } else if (ch === '\r') {
      if (text[i + 1] === '\n') i += 1;
      endRow();
    } else if (ch === '\n') {
      endRow();
    } else {
      field += ch;
      endedRow = false;
    }
  }

  if (!endedRow) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

export function toObjects(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return [];

  const header = rows[0];
  const objects = [];

  for (let r = 1; r < rows.length; r += 1) {
    const row = rows[r];
    const obj = {};
    for (let c = 0; c < header.length; c += 1) {
      const value = row[c];
      obj[header[c]] = value === undefined ? '' : value;
    }
    objects.push(obj);
  }

  return objects;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, toObjects } from './csv.js';

test('splits simple rows on commas and LF', () => {
  assert.deepEqual(parseCsv('a,b\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
});

test('handles CRLF line endings', () => {
  assert.deepEqual(parseCsv('a,b\r\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
});

test('quoted fields may contain commas', () => {
  assert.deepEqual(parseCsv('"a,b",c'), [['a,b', 'c']]);
});

test('quoted fields may contain line breaks', () => {
  assert.deepEqual(parseCsv('"a\nb",c\nd,e'), [
    ['a\nb', 'c'],
    ['d', 'e'],
  ]);
});

test('doubled quotes inside a quoted field mean one quote', () => {
  assert.deepEqual(parseCsv('"say ""hi""",x'), [['say "hi"', 'x']]);
});

test('a final line break adds no empty row', () => {
  assert.deepEqual(parseCsv('a,b\n'), [['a', 'b']]);
  assert.deepEqual(parseCsv('a,b\r\n'), [['a', 'b']]);
});

test('empty text gives an empty array', () => {
  assert.deepEqual(parseCsv(''), []);
});

test('empty fields are kept', () => {
  assert.deepEqual(parseCsv('a,,c'), [['a', '', 'c']]);
});

test('toObjects uses the first row as the header', () => {
  assert.deepEqual(toObjects(parseCsv('name,age\nAda,36\nBob,40')), [
    { name: 'Ada', age: '36' },
    { name: 'Bob', age: '40' },
  ]);
});

test('toObjects gives short rows empty strings for missing columns', () => {
  assert.deepEqual(toObjects(parseCsv('name,age,email\nAda,36')), [
    { name: 'Ada', age: '36', email: '' },
  ]);
});

test('toObjects with only a header returns no objects', () => {
  assert.deepEqual(toObjects(parseCsv('name,age')), []);
});

